-- Zwis na drążku (Początkujący, baza przypisań mięśni: id 1102)
INSERT INTO exercises (name, slug, main_muscle_group, secondary_muscle_groups, equipment, required_equipment_all, equipment_other, training_location, difficulty_level, movement_pattern, description, execution_instructions, common_mistakes, coaching_tips, exercise_type, safety_notes, suitable_experience_levels, training_goals, execution, requires_spotter, can_be_performed_to_failure, joint_stress, learning_difficulty, exercise_priority, suitable_for_no_activity, movement_complexity, is_active, role, verification_status, joint_stress_areas, source, review_batch, reviewed_by_trainer, hidden, unilateral, movement_category, plane_of_motion, neurological_fatigue, doms_potential, resistance_type, default_duration_seconds)
SELECT 'Zwis na drążku', 'zwis-na-drazku', 'Plecy', ARRAY['Biceps','Przedramiona','Barki']::text[], ARRAY['Drążek']::text[], ARRAY[]::text[], NULL, ARRAY['Siłownia','Dom','Plener']::text[], 'Początkujący', 'Przyciąganie pionowe', 'Zwis na drążku na prostych rękach z lekko ściągniętymi łopatkami. Przygotowuje chwyt i barki do podciągania.', 'Chwyć drążek nachwytem na szerokość barków. Zwiśnij na prostych rękach, nogi oderwane od podłogi lub lekko ugięte. Ściągnij łopatki lekko w dół i utrzymaj pozycję 10–30 sekund.', 'Barki podciągnięte do uszu, bujanie ciałem, wstrzymywanie oddechu.', 'Zacznij od krótkich zwisów i dokładaj sekundy. Oddychaj spokojnie. Łatwiej: stopy na podłodze i część ciężaru na nogach.', 'Izolowane', 'Użyj stabilnego drążka, który udźwignie Twój ciężar. Przerwij przy bólu barku lub łokcia. Wykonuj w komfortowym zakresie.', ARRAY['Początkujący','Średniozaawansowany','Zaawansowany']::text[], ARRAY['Poprawa sprawności','Zwiększenie siły']::text[], 'Obustronne', false, 'Nie', 'Średnie', 1, 'Średni', false, 'Prosta', true, 'pomocnicze', 'zweryfikowane', ARRAY['Bark','Łokieć']::text[], 'own', 'katalog-decyzje-0057', true, false, false, 'Pull', 'Strzałkowa', 1, 1, 'Masa własnego ciała', 20
WHERE NOT EXISTS (SELECT 1 FROM exercises WHERE slug = 'zwis-na-drazku');
INSERT INTO exercise_muscle_assignments (exercise_id, specific_muscle_id, is_primary, coefficient)
SELECT n.id, a.specific_muscle_id, a.is_primary, a.coefficient FROM exercises n JOIN exercise_muscle_assignments a ON a.exercise_id = 1102
WHERE n.slug = 'zwis-na-drazku' AND NOT EXISTS (SELECT 1 FROM exercise_muscle_assignments z WHERE z.exercise_id = n.id);
INSERT INTO exercise_ladder_steps (pattern, step_order, level, exercise_id)
SELECT 'Kalistenika: podciąganie', 1, 'Początkujący', id FROM exercises WHERE slug = 'zwis-na-drazku'
ON CONFLICT (pattern, exercise_id) DO NOTHING;

-- Negatywy podciągnięcia (Średniozaawansowany, baza przypisań mięśni: id 2)
INSERT INTO exercises (name, slug, main_muscle_group, secondary_muscle_groups, equipment, required_equipment_all, equipment_other, training_location, difficulty_level, movement_pattern, description, execution_instructions, common_mistakes, coaching_tips, exercise_type, safety_notes, suitable_experience_levels, training_goals, execution, requires_spotter, can_be_performed_to_failure, joint_stress, learning_difficulty, exercise_priority, suitable_for_no_activity, movement_complexity, is_active, role, verification_status, joint_stress_areas, source, review_batch, reviewed_by_trainer, hidden, unilateral, movement_category, plane_of_motion, neurological_fatigue, doms_potential, resistance_type)
SELECT 'Negatywy podciągnięcia', 'negatywy-podciagniecia', 'Plecy', ARRAY['Biceps','Barki','Przedramiona']::text[], ARRAY['Drążek']::text[], ARRAY[]::text[], 'Podpórka lub skok, żeby wejść nad drążek', ARRAY['Siłownia','Dom','Plener']::text[], 'Średniozaawansowany', 'Przyciąganie pionowe', 'Wejdź nad drążek (ze skoku lub z podpórki) i opuszczaj ciało powoli, 3–5 sekund, aż do pełnego zwisu. Buduje siłę do pierwszego podciągnięcia.', 'Ustaw się nad drążkiem z brodą powyżej niego (wskocz lub użyj podpórki). Opuszczaj ciało powoli przez 3–5 sekund do pełnego wyprostu rąk. Zejdź z drążka, wróć na górę i powtórz.', 'Zbyt szybkie opadanie, bujanie ciałem, niepełny zwis na dole.', 'Licz sekundy w głowie. Łopatki aktywne przez cały ruch. Mało powtórzeń, ale wolno.', 'Złożone', 'Użyj stabilnego drążka. Kontroluj opadanie i nie puszczaj drążka w dole. Przy bólu barku lub łokcia przerwij.', ARRAY['Średniozaawansowany','Zaawansowany']::text[], ARRAY['Zwiększenie siły','Budowa sylwetki','Poprawa sprawności']::text[], 'Obustronne', false, 'Nie', 'Średnie', 3, 'Średni', false, 'Umiarkowana', true, 'główne', 'zweryfikowane', ARRAY['Bark','Łokieć']::text[], 'own', 'katalog-decyzje-0057', true, false, false, 'Pull', 'Strzałkowa', 3, 4, 'Masa własnego ciała'
WHERE NOT EXISTS (SELECT 1 FROM exercises WHERE slug = 'negatywy-podciagniecia');
