SELECT n.id, a.specific_muscle_id, a.is_primary, a.coefficient FROM exercises n JOIN exercise_muscle_assignments a ON a.exercise_id = 2
WHERE n.slug = 'negatywy-podciagniecia' AND NOT EXISTS (SELECT 1 FROM exercise_muscle_assignments z WHERE z.exercise_id = n.id);
